#!/usr/bin/env python3
from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[1] / "upstream"
client_probe = ROOT / "fabric/src/main/java/org/valkyrienskies/mod/fabric/client/GateEClientProbe.java"
server_probe = ROOT / "fabric/src/main/kotlin/org/valkyrienskies/mod/fabric/common/GateDProbe.kt"

# Production-world #622 proves the old Phase70 one-shot -0.08 Y fixture probe is now harmful:
# after normalization the LocalPlayer follows that seeded vanilla-gravity descent while native
# Create horizontal carry is already exact, so the smoke can sink below the train before the later
# M1 input fixture begins. Phase197 already proves the real vertical requirement with a native
# vanilla jump followed by natural fall/landing. Keep Phase68's zero-motion client normalization and
# preserve Phase70's useful block-referenced server surface selection, but inject no fake gravity.
# This remains smoke-fixture setup only; gameplay carry/collision/physics are untouched.
client = client_probe.read_text(encoding="utf-8")
client_surface = '''                                    player.setPos(worldTarget.x, worldTarget.y, worldTarget.z);\n                                    player.setDeltaMovement(Vec3.ZERO);\n                                    LOGGER.info(\n                                        "GATE_E_FIXTURE_COLLIDER_REPOSITIONED collider_index={} local_top={} old_vertical_gap={} target={},{},{}",'''
if client_surface not in client:
    raise SystemExit("Phase 70 could not find Phase 67/68 zero-motion client surface normalization")
client_probe.write_text(client, encoding="utf-8")

# Phase 69 chose the globally nearest collider to the save position. That picked a
# lower surface because it was slightly closer in Z, while the client first chose
# the nearest contraption block top and then its real collision surface. Mirror
# that two-stage reference server-side: choose the simplified collider surface
# closest to the nearest block-top reference, then leave the normalized player at
# zero injected motion so Create/Minecraft collision and gravity are the only runtime mechanisms.
server = server_probe.read_text(encoding="utf-8")
old_server = '''                                var best = -1\n                                var bestTop = 0.0\n                                var bestX = 0.0\n                                var bestZ = 0.0\n                                var bestLocalDistanceSq = Double.POSITIVE_INFINITY\n                                for (i in 0 until size) {\n                                    val minX = cx[i] - ex[i] - eps\n                                    val maxX = cx[i] + ex[i] + eps\n                                    val minZ = cz[i] - ez[i] - eps\n                                    val maxZ = cz[i] + ez[i] + eps\n                                    val top = cy[i] + ey[i]\n                                    val targetX = localFeet.x.coerceIn(minX, maxX)\n                                    val targetZ = localFeet.z.coerceIn(minZ, maxZ)\n                                    val dx = targetX - localFeet.x\n                                    val dy = top - localFeet.y\n                                    val dz = targetZ - localFeet.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    if (distanceSq < bestLocalDistanceSq) {\n                                        bestLocalDistanceSq = distanceSq\n                                        bestTop = top\n                                        bestX = targetX\n                                        bestZ = targetZ\n                                        best = i\n                                    }\n                                }\n                                if (best >= 0) {\n                                    val localTarget = net.minecraft.world.phys.Vec3(bestX, bestTop, bestZ)\n                                    val target = toGlobal.invoke(carriage, localTarget, 0.0f) as net.minecraft.world.phys.Vec3\n                                    val dx = target.x - player.x\n                                    val dy = target.y - player.y\n                                    val dz = target.z - player.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    player.setPos(target.x, target.y, target.z)\n                                    player.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO)\n                                    logger.info(\n                                        "GATE_D_FIXTURE_PLAYER_REPOSITIONED old_distance_sq={} local_distance_sq={} target={},{},{} source=nearest_simplified_collider_surface collider_index={} local_top={}",\n                                        distanceSq, bestLocalDistanceSq, target.x, target.y, target.z, best, bestTop)\n                                    return@register\n                                }'''
new_server = '''                                var referenceLocal = localFeet\n                                var referenceWorldDistanceSq = Double.POSITIVE_INFINITY\n                                for (key in blocks.keys) {\n                                    val pos = key as? net.minecraft.core.BlockPos ?: continue\n                                    val localBlockTop = net.minecraft.world.phys.Vec3(pos.x + 0.5, pos.y + 1.0, pos.z + 0.5)\n                                    val worldBlockTop = toGlobal.invoke(carriage, localBlockTop, 0.0f) as? net.minecraft.world.phys.Vec3 ?: continue\n                                    val dx = worldBlockTop.x - player.x\n                                    val dy = worldBlockTop.y - player.y\n                                    val dz = worldBlockTop.z - player.z\n                                    val d2 = dx * dx + dy * dy + dz * dz\n                                    if (d2 < referenceWorldDistanceSq) {\n                                        referenceWorldDistanceSq = d2\n                                        referenceLocal = localBlockTop\n                                    }\n                                }\n\n                                var best = -1\n                                var bestTop = 0.0\n                                var bestX = 0.0\n                                var bestZ = 0.0\n                                var bestReferenceDistanceSq = Double.POSITIVE_INFINITY\n                                for (i in 0 until size) {\n                                    val minX = cx[i] - ex[i] - eps\n                                    val maxX = cx[i] + ex[i] + eps\n                                    val minZ = cz[i] - ez[i] - eps\n                                    val maxZ = cz[i] + ez[i] + eps\n                                    val top = cy[i] + ey[i]\n                                    val targetX = referenceLocal.x.coerceIn(minX, maxX)\n                                    val targetZ = referenceLocal.z.coerceIn(minZ, maxZ)\n                                    val dx = targetX - referenceLocal.x\n                                    val dy = top - referenceLocal.y\n                                    val dz = targetZ - referenceLocal.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    if (distanceSq < bestReferenceDistanceSq) {\n                                        bestReferenceDistanceSq = distanceSq\n                                        bestTop = top\n                                        bestX = targetX\n                                        bestZ = targetZ\n                                        best = i\n                                    }\n                                }\n                                if (best >= 0) {\n                                    val localTarget = net.minecraft.world.phys.Vec3(bestX, bestTop, bestZ)\n                                    val target = toGlobal.invoke(carriage, localTarget, 0.0f) as net.minecraft.world.phys.Vec3\n                                    val dx = target.x - player.x\n                                    val dy = target.y - player.y\n                                    val dz = target.z - player.z\n                                    val distanceSq = dx * dx + dy * dy + dz * dz\n                                    player.setPos(target.x, target.y, target.z)\n                                    player.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO)\n                                    logger.info(\n                                        "GATE_D_FIXTURE_PLAYER_REPOSITIONED old_distance_sq={} reference_distance_sq={} collider_reference_distance_sq={} target={},{},{} source=block_reference_simplified_surface collider_index={} local_top={} zero_injected_motion=true",\n                                        distanceSq, referenceWorldDistanceSq, bestReferenceDistanceSq, target.x, target.y, target.z, best, bestTop)\n                                    return@register\n                                }'''
if old_server not in server:
    raise SystemExit("Phase 70 could not find Phase 69 server nearest-collider selector")
server = server.replace(old_server, new_server, 1)
server_probe.write_text(server, encoding="utf-8")

# Guard only the Phase70 replacement itself. The generated probes contain older
# diagnostic code from earlier phases, so scanning the entire files for a numeric
# velocity literal can reject unrelated code before the production client even builds.
if "player.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO)" not in new_server:
    raise SystemExit("Phase 70 lost zero-motion server fixture normalization")
if "player.setDeltaMovement(Vec3.ZERO)" not in client_surface:
    raise SystemExit("Phase 70 lost zero-motion client fixture normalization")

print("Phase 70: synchronized the fixture on the block-referenced simplified collision surface with zero injected motion; native Create/Minecraft gravity and collision own M1")

runpy.run_path(str(Path(__file__).with_name("prepare_vs2_26_2_phase71.py")), run_name="__main__")
